// 1. Read rows from Google Sheets
const allRows = $input.all().map(i => i.json).filter(r => r && Object.keys(r).length > 0);
const firstRow = allRows[0] || {};
const prodKey = Object.keys(firstRow).find(k => k.toLowerCase().includes('produkt') || k.toLowerCase().includes('product')) || 'Produkt';

// Filter stocked rows (non-empty product) so AI only sees genuine inventory
const stockedRows = allRows.filter(r => r[prodKey] && String(r[prodKey]).trim().length > 0);
const rows = stockedRows.length > 0 ? stockedRows : allRows;

// 2. Read user message from Chat Trigger
const chatNode = $('Chat Trigger').first().json;
const chatInput = String(chatNode.chatInput || chatNode.message || chatNode.text || '').trim();

// 3. Analyze format of existing data (columns, units, categories, locations)
const sheetData = JSON.stringify(rows, null, 2);
const columnsList = Object.keys(firstRow).join(', ') || 'Lp., Produkt, Kategoria, Ilość, Jednostka, Minimum, Data ważności, Miejsce, Status';

const getUniqueValues = (fieldKeywords) => {
  const key = Object.keys(firstRow).find(k => fieldKeywords.some(w => k.toLowerCase().includes(w)));
  if (!key) return [];
  return [...new Set(rows.map(r => r[key]).filter(Boolean))];
};

const existingUnits = getUniqueValues(['jednostka', 'unit', 'jm']);
const existingCategories = getUniqueValues(['kategoria', 'category']);
const existingLocations = getUniqueValues(['lokalizacja', 'miejsce', 'location']);

let formatInfo = `KOLUMNY W TWOIM ARKUSZU: ${columnsList}
`;
if (existingUnits.length) formatInfo += `UŻYWANE W TABELI JEDNOSTKI: ${existingUnits.join(', ')}
`;
if (existingCategories.length) formatInfo += `UŻYWANE W TABELI KATEGORIE: ${existingCategories.join(', ')}
`;
if (existingLocations.length) formatInfo += `UŻYWANE W TABELI MIEJSCA/LOKALIZACJE: ${existingLocations.join(', ')}
`;

// 4. System prompt with strict grounding, format preservation, bilingual support, and no-question policy
const systemPrompt = `Jesteś inteligentnym asystentem domowej spiżarni i magazynu, zintegrowanym z Arkuszem Google.
Twoim zadaniem jest odpowiadanie na pytania kulinarne i magazynowe oraz ZARZĄDZANIE STANEM W ARKUSZU (dodawanie produktów, zmiana ilości, zdejmowanie ze stanu).

${formatInfo}
ZASADY JĘZYKOWE I FORMATOWANIA (BARDZO WAŻNE):
1. JĘZYK ODPOWIEDZI DLA UŻYTKOWNIKA (pole "reply"):
   - Odpowiadaj DOKŁADNIE w tym języku, w którym użytkownik napisał wiadomość:
     * Jeśli użytkownik pisze po angielsku -> odpowiedz w "reply" po angielsku (np. "✅ Updated stock: Mleko UHT is now 8 pcs", "To make pancakes you need flour, milk, and eggs...").
     * Jeśli użytkownik pisze po polsku -> odpowiedz w "reply" po polsku (np. "✅ Zaktualizowałem stan: Mleko UHT ma teraz 8 szt.", "Do naleśników potrzebujesz mąki, mleka i jajek...").
   - W treści "reply" (niezależnie od języka odpowiedzi) nazwy produktów, kategorii i lokalizacji podawaj tak, jak występują w arkuszu (czyli po polsku, np. Makaron spaghetti, Szafka górna, Nabiał), aby użytkownik łatwo odnalazł je w tabeli.

2. DANE W ARKUSZU (pole "rows" lub "row"):
   - Arkusz Google jest prowadzony w języku polskim!
   - W obiektach wierszy WSZYSTKIE wartości i klucze MUSZĄ BYĆ PO POLSKU, dokładnie w stylu i wartościach występujących w tabeli (np. Kategoria: "Makarony i kasze", Jednostka: "opak.", Miejsce: "Szafka górna", Status: "✔ OK" lub "⚠ Uzupełnij").
   - Nawet jeśli użytkownik wydał polecenie po angielsku (np. "Add whole grain bread"), w obiekcie wiersza wpisz po polsku: Produkt: "Chleb pełnoziarnisty", Jednostka: "szt.", Miejsce: "Szafka dolna", Kategoria: "Pieczywo".
   - Dla istniejących produktów w polu "Produkt" użyj DOKŁADNIE oryginalnej polskiej nazwy z tabeli.
   - JEDNOSTKI: Używaj wyłącznie skrótów jednostek z arkusza (${existingUnits.join(', ') || 'opak., kg, puszka, słoik, but., szt., kostka'}).
   - KATEGORIE I MIEJSCA: Przypisuj wyłącznie wartości z listy występującej w arkuszu (${existingCategories.join(', ') || 'Makarony i kasze, Nabiał, Pieczywo, Inne'} / ${existingLocations.join(', ') || 'Szafka górna, Szafka dolna, Blat, Spiżarnia, Lodówka'}).
   - LICZBY: W kolumnie ilości oraz minimum wpisuj wyłącznie czyste liczby (np. 1 lub 0.5), bez dopisywania jednostki.
   - STATUS: Jeśli Ilość <= Minimum, ustaw "⚠ Uzupełnij". Jeśli Ilość > Minimum, ustaw "✔ OK".
   - DATA WAŻNOŚCI: W formacie YYYY-MM-DD. Oszacuj rozsądny termin.
   - KOMPLETNOŚĆ WIERSZA: W obiektach wierszy zwróć DOKŁADNIE klucze odpowiadające kolumnom arkusza (${columnsList}). NIE dodawaj dodatkowych metadanych.

3. NOWE PRODUKTY (BEZWZGLĘDNY ZAKAZ DOPYTYWANIA!):
   - NIGDY NIE ZADAWAJ UŻYTKOWNIKOWI PYTAŃ DOPYTUJĄCYCH o brakujące parametry (np. o Miejsce, Jednostkę, Kategorię czy Minimum)!
   - Jeśli użytkownik podał tylko nazwę nowego produktu lub nie określił wszystkich szczegółów, Twoim BEZWZGLĘDNYM OBOWIĄZKIEM jest SAMODZIELNIE I AUTOMATYCZNIE dobrać najbardziej logiczne wartości z istniejącej tabeli:
     * Miejsce: przypisz najbardziej logiczną półkę/miejsce z istniejących w arkuszu (np. dla chleba: 'Szafka dolna' lub 'Blat' lub 'Spiżarnia').
     * Kategoria: przypisz pasującą kategorię (np. 'Pieczywo' lub 'Inne').
     * Jednostka: przypisz logiczną jednostkę (np. 'szt.' lub 'opak.').
     * Minimum: ustaw domyślnie 1.
     * Ilość: jeśli użytkownik nie podał liczby, ustaw domyślnie 1.
     * Data ważności: oszacuj rozsądny termin (np. pieczywo: 3-5 dni, nabiał: 1-2 tyg., suche: 1 rok).
   - NATYCHMIAST DODAJ TEN PRODUKT DO ARKUSZA (ustaw "action": "update")! Nie odkładaj dodania na później i nie pytaj użytkownika. W treści "reply" po prostu poinformuj, co dodałeś i z jakimi parametrami.

4. OBSŁUGA KILKU PRODUKTÓW W JEDNYM POLECENIU:
   - Jeśli użytkownik w jednej wiadomości prosi o modyfikację lub dodanie kilku produktów (np. "kupiłem 2 mleka i chleb", "I bought 2 milks and whole grain bread"):
     * Ustaw "action": "update".
     * W tablicy "rows" podaj obiekty dla KAŻDEGO z wymienionych produktów (zaktualizuj istniejący produkt ORAZ od razu dodaj nowy produkt z dobranymi domyślnymi parametrami!).
     * W polu "reply" napisz jedno łączne podsumowanie operacji.

TWOJE ZADANIA:
1. MODYFIKACJA STANU (np. "kupiłem 2 mleka", "I bought 2 cartons of milk", "zmień ilość jajek na 10", "zdejmij ze stanu mleko", "dodaj chleb", "bought bread and milk"):
   - Ustaw pole "action": "update".
   - W polu "reply" napisz zwięzłe, przyjazne potwierdzenie w języku użytkownika (PL lub EN).
   - W tablicy "rows" (lub obiekcie "row") podaj dane wierszy do zapisu/aktualizacji (zawsze po polsku, tak jak w arkuszu).

2. PYTANIA I PRZEPISY (np. "chcę zrobić naleśniki, czego brakuje?", "I want to make pancakes, do I have the ingredients?", "co mogę ugotować?", "what are we running low on?", "ile mamy jajek?"):
   - Ustaw pole "action": "answer".
   - Pola "rows" i "row" ustaw na null.
   - W polu "reply" udziel wyczerpującej, sformatowanej w Markdown odpowiedzi w języku pytania użytkownika (użyj wiedzy kulinarnej i porównaj składniki ze stanem spiżarni w tabeli).

3. TEMATY NIEZWIĄZANE (np. polityka, historia, pogoda):
   - Ustaw pole "action": "answer", "rows": null, "row": null.
   - W polu "reply" odmów w języku pytania użytkownika:
     * Po polsku: "W arkuszu nie ma informacji na ten temat - pomagam wyłącznie w sprawdzaniu i aktualizacji zapasów oraz planowaniu kuchni."
     * Po angielsku: "There is no information about this in the sheet - I only assist with checking and updating pantry inventory and meal planning."

ODPOWIADAJ WYŁĄCZNIE W POPRAWNYM FORMACIE JSON:
{
  "action": "update" | "answer",
  "reply": "tekst odpowiedzi lub potwierdzenia dla użytkownika (w języku pytania: PL lub EN)",
  "rows": [
    { "Lp.": 71, "Produkt": "...", "Kategoria": "...", "Ilość": 1, "Jednostka": "...", "Minimum": 1, "Data ważności": "2027-12-31", "Miejsce": "...", "Status": "..." }
  ]
}`;

const userPrompt = `DANE Z ARKUSZA GOOGLE (GOOGLE SHEET DATA):
${sheetData}

POLECENIE / WIADOMOŚĆ UŻYTKOWNIKA (USER MESSAGE):
${chatInput || '(brak pytania - przedstaw się i napisz w czym możesz pomóc / please introduce yourself and ask how you can help)'}`;

const fullPrompt = `${systemPrompt}

========================================
${userPrompt}`;

return [{
  json: {
    chatInput,
    rowCount: rows.length,
    payload: {
      contents: [
        {
          parts: [
            { text: fullPrompt }
          ]
        }
      ],
      generationConfig: {
        temperature: 0.1,
        responseMimeType: "application/json",
        maxOutputTokens: 8192
      }
    }
  }
}];

// Parsowanie odpowiedzi JSON wygenerowanej przez Gemini
const resp = $input.first().json;
let parsed = null;

try {
  const candidate = resp.candidates && resp.candidates[0];
  if (candidate && candidate.content && candidate.content.parts) {
    const validParts = candidate.content.parts.filter(p => !p.thought);
    const partsToUse = validParts.length > 0 ? validParts : candidate.content.parts;
    const rawText = partsToUse.map(p => p.text || '').join('').trim();
    const cleaned = rawText.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/i, '').trim();
    parsed = JSON.parse(cleaned);
  } else if (resp.text) {
    parsed = JSON.parse(resp.text);
  }
} catch (e) {
  parsed = null;
}

if (!parsed || typeof parsed !== 'object') {
  return [{
    json: {
      action: 'answer',
      reply: '⚠️ Nie udało się zinterpretować polecenia. Spróbuj zadać je ponownie.'
    }
  }];
}

// Jeśli akcją jest modyfikacja arkusza i mamy wiersz lub wiersze do zapisu
if (parsed.action === 'update') {
  const rowList = Array.isArray(parsed.rows) ? parsed.rows : (parsed.row && typeof parsed.row === 'object' ? [parsed.row] : []);
  if (rowList.length > 0) {
    return rowList.map(r => ({
      json: {
        ...r,
        action: 'update',
        reply: parsed.reply || '✅ Zaktualizowano arkusz.'
      }
    }));
  }
}

// W przeciwnym razie zwykła odpowiedź tekstowa
return [{
  json: {
    action: 'answer',
    reply: parsed.reply || 'Gotowe!'
  }
}];

// 1. Get column headers from the initial Google Sheets read
const rawSheetRows = $('Google Sheets (Read)').all();
const validColumns = rawSheetRows.length > 0 ? Object.keys(rawSheetRows[0].json).filter(k => k && !k.startsWith('_')) : [];

const prodKey = validColumns.find(k => k.toLowerCase().includes('produkt') || k.toLowerCase().includes('product')) || 'Produkt';
const lpKey = validColumns.find(k => k.toLowerCase().includes('lp')) || 'Lp.';
const qtyKey = validColumns.find(k => k.toLowerCase().includes('ilość') || k.toLowerCase().includes('ilosc')) || 'Ilość';
const minKey = validColumns.find(k => k.toLowerCase().includes('minimum') || k.toLowerCase().includes('min')) || 'Minimum';
const statusKey = validColumns.find(k => k.toLowerCase().includes('status')) || 'Status';

// Track occupied rows so multiple new products in one batch get distinct consecutive empty rows
const occupiedRows = rawSheetRows.map(r => ({ ...r.json }));
const allInputs = $input.all().map(i => i.json);
const results = [];

for (const input of allInputs) {
  const cleanRow = {};
  const productName = input[prodKey] || input.Produkt || '';
  const existingRow = occupiedRows.find(r => r && r[prodKey] && String(r[prodKey]).trim().toLowerCase() === String(productName).trim().toLowerCase());

  // 3. Fill genuine columns
  if (validColumns.length > 0) {
    for (const col of validColumns) {
      if (input[col] !== undefined) {
        cleanRow[col] = input[col];
      } else if (existingRow && existingRow[col] !== undefined) {
        cleanRow[col] = existingRow[col];
      }
    }
  } else {
    for (const [key, value] of Object.entries(input)) {
      if (key !== 'action' && key !== 'reply' && !key.startsWith('_')) {
        cleanRow[key] = value;
      }
    }
  }

  // 4. Handle index Lp. (preserve original Lp. for existing items, or use first available empty row)
  if (existingRow && existingRow[lpKey]) {
    cleanRow[lpKey] = existingRow[lpKey];
  } else {
    // Find first available empty row in sheet
    const emptyRow = occupiedRows.find(r => r && (!r[prodKey] || String(r[prodKey]).trim() === ''));
    if (emptyRow && emptyRow[lpKey] !== undefined && String(emptyRow[lpKey]).trim() !== '') {
      const parsedLp = parseInt(String(emptyRow[lpKey]), 10);
      cleanRow[lpKey] = !isNaN(parsedLp) ? parsedLp : emptyRow[lpKey];
      // Mark this row as occupied for the next new product in the batch
      emptyRow[prodKey] = productName;
    } else {
      const maxLp = occupiedRows.reduce((max, r) => {
        const val = parseInt(r && r[lpKey], 10);
        return !isNaN(val) && val > max ? val : max;
      }, 0);
      cleanRow[lpKey] = maxLp + 1;
      occupiedRows.push({ [lpKey]: cleanRow[lpKey], [prodKey]: productName });
    }
  }

  // 5. Enforce numeric values for quantity and minimum
  if (cleanRow[qtyKey] !== undefined) {
    const num = parseFloat(String(cleanRow[qtyKey]).replace(',', '.'));
    if (!isNaN(num)) cleanRow[qtyKey] = num;
  }
  if (cleanRow[minKey] !== undefined) {
    const num = parseFloat(String(cleanRow[minKey]).replace(',', '.'));
    if (!isNaN(num)) cleanRow[minKey] = num;
  }

  // 6. Recalculate Status based on threshold rules
  if (statusKey && cleanRow[qtyKey] !== undefined && cleanRow[minKey] !== undefined) {
    const qty = Number(cleanRow[qtyKey]);
    const min = Number(cleanRow[minKey]);
    if (!isNaN(qty) && !isNaN(min)) {
      cleanRow[statusKey] = (qty <= min) ? '⚠ Uzupełnij' : '✔ OK';
    }
  }

  results.push({ json: cleanRow });
}

return results;

// Send confirmation message back to chat
const decision = $('Parse AI Decision').first().json;
const reply = decision.reply || '✅ Pomyślnie zaktualizowano dane w Arkuszu Google!';
return [{ json: { output: reply } }];

// Send standard answer back to chat
const item = $input.first().json;
const reply = item.reply || 'Gotowe!';
return [{ json: { output: reply } }];
